import{_ as r,a0 as a,w as s,s as p,I as n,x as i,a1 as o,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在Linux下使用Gitblit工具創建Git倉庫服務 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux下使用Gitblit工具創建Git倉庫服務 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux下使用Gitblit工具創建Git倉庫服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux下使用Gitblit工具創建Git倉庫服務 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150330 How to Serve Git Repositories Using Gitblit Tool in Linux","title":"如何在Linux下使用Gitblit工具創建Git倉庫服務","tag":"201506","desc":""},"relativePath":"201506/20150330 How to Serve Git Repositories Using Gitblit Tool in Linux.md","filePath":"[post].md"}'),g={name:"201506/20150330 How to Serve Git Repositories Using Gitblit Tool in Linux.md"};function u(b,t,m,h,x,G){const e=a("Link");return s(),p("div",null,[t[18]||(t[18]=n("h1",{id:"如何在linux下使用gitblit工具創建git倉庫服務",tabindex:"-1"},[i("如何在Linux下使用Gitblit工具創建Git倉庫服務 "),n("a",{class:"header-anchor",href:"#如何在linux下使用gitblit工具創建git倉庫服務","aria-label":"Permalink to “如何在Linux下使用Gitblit工具創建Git倉庫服務”"},"​")],-1)),n("p",null,[t[1]||(t[1]=i("嗨！朋友，今天我們將學習如何在你的Linux服務器或者PC上安裝Gitblit工具。首先，我們看看什麼是Git，它的功能以及安裝Gitblit的步驟。",-1)),o(e,{href:"http://git-scm.com/"},{default:l(()=>[...t[0]||(t[0]=[i("Git是分佈式版本控制系統",-1)])]),_:1}),t[2]||(t[2]=i("，它強調速度、數據一致性，並且支持分佈式、非線性工作流。它最初由Linus Torvalds在2005年為Linux內核設計和開發，使用GPLv2證書，並從此成為軟件開發中使用最廣泛的版本控制系統。",-1))]),n("p",null,[o(e,{href:"http://gitblit.com/"},{default:l(()=>[...t[3]||(t[3]=[i("Gitblit是完全開源的軟件",-1)])]),_:1}),t[4]||(t[4]=i("，它基於純粹的Java堆棧，被設計以在Git倉庫速度和效率方面勝任從小型到極大型的項目。它很容易學習和上手，並有着閃電般的性能。它在很多方面遠勝 Subversion、CVS、Perforce和ClearCase等SCM（版本控制）工具，比如，如快速本地分支、易於暫存、多工作流等。",-1))]),t[19]||(t[19]=d(`<h4 id="gitblit的功能" tabindex="-1">Gitblit的功能 <a class="header-anchor" href="#gitblit的功能" aria-label="Permalink to “Gitblit的功能”">​</a></h4><ul><li>它可以做為一個啞倉庫視圖，沒有管理控制以及用户賬户。</li><li>它可以做為完整的Git服務，擁有克隆、推送和倉庫訪問控制。</li><li>它能獨立於其他Git工具使用（包括實際的Git），它能和您已有的工具協作。</li></ul><h3 id="_1-創建gitblit安裝目錄" tabindex="-1">1.創建Gitblit安裝目錄 <a class="header-anchor" href="#_1-創建gitblit安裝目錄" aria-label="Permalink to “1.創建Gitblit安裝目錄”">​</a></h3><p>首先我們將在我們的服務器上建立一個目錄，並在該目錄下安裝最新的Gitblit。</p><pre><code>$ sudo mkdir -p /opt/gitblit

$ cd /opt/gitblit
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/creating-directory-gitblit.png" alt="創建gitblit目錄"></p><h3 id="_2-下載並解壓" tabindex="-1">2. 下載並解壓 <a class="header-anchor" href="#_2-下載並解壓" aria-label="Permalink to “2. 下載並解壓”">​</a></h3><p>現在，我們將從Gitblit官方站點下載最新版的Gitblit。這裏我們將安裝1.6.2版本。所以，請在安裝時根據具體的版本對命令進行修改。</p><pre><code>$ sudo wget http://dl.bintray.com/gitblit/releases/gitblit-1.6.2.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/downloading-gitblit.png" alt="下載gitblit安裝包"></p><p>接下來，我們將下載到的tar壓縮包解壓至之前創建的目錄 /opt/gitblit/</p><pre><code>$ sudo tar -zxvf gitblit-1.6.2.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/extracting-gitblit-tar.png" alt="解壓gitblit壓縮包"></p><h3 id="_3-配置並運行" tabindex="-1">3.配置並運行 <a class="header-anchor" href="#_3-配置並運行" aria-label="Permalink to “3.配置並運行”">​</a></h3><p>現在，我們將對Gitblit進行配置。如果你想要定製Gitblit的行為，你可以修改<code>gitblit/data/gitblit.properties</code>。在完成配置後，我們將運行安裝好的gitblit。有兩種方式來運行gitblit，第一種是通過下面的命令手動運行：</p><pre><code>$ sudo java -jar gitblit.jar --baseFolder data
</code></pre><p>另一種是將gitblit添加為服務。下面是在linux下將gitblit添加為服務的步驟。</p><p>由於我在使用Ubuntu，下面的命令將是 sudo cp service-ubuntu.sh /etc/init.d/gitblit，所以請根據你的發行版修改文件名service-ubuntu.sh為相應的你運行的發行版。</p><pre><code>$ sudo ./install-service-ubuntu.sh

$ sudo service gitblit  start
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/starting-gitblit-service.png" alt="啓動gitblit服務"></p><p>在你的瀏覽器中打開<code>http://localhost:8080</code>或<code>https://localhost:8443</code>，也可以將localhost根據本地配置替換為IP地址。輸入默認的管理員憑證：admin / admin並點擊login按鈕。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/gitblit-welcome.png" alt="gitblit歡迎頁面"></p><p>現在，我們將添加一個新的用户。首先，你需要以admin用户登錄，username = <strong>admin</strong>，password = <strong>admin</strong>。</p><p>然後，點擊用户圖標 &gt; users &gt; (+) new user 來創建一個新用户，如下圖所示。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/add-user.png" alt="添加新用户"></p><p>現在，我們將創建一個開箱可用的倉庫。點擊 repositories &gt; (+) new repository。然後，如下圖所示添加新的倉庫。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/add-new-repository.png" alt="添加新的倉庫"></p><h4 id="使用命令列創建一個新的倉庫" tabindex="-1">使用命令列創建一個新的倉庫 <a class="header-anchor" href="#使用命令列創建一個新的倉庫" aria-label="Permalink to “使用命令列創建一個新的倉庫”">​</a></h4><pre><code>    touch README.md
    git init
    git add README.md
    git commit -m &quot;first commit&quot;
    git remote add origin ssh://arunlinoxide@localhost:29418/linoxide.com.git
    git push -u origin master
</code></pre><p>請將其中的用户名arunlinoxide替換為你添加的用户名。</p><h4 id="在命令列中push一個已存在的倉庫" tabindex="-1">在命令列中push一個已存在的倉庫 <a class="header-anchor" href="#在命令列中push一個已存在的倉庫" aria-label="Permalink to “在命令列中push一個已存在的倉庫”">​</a></h4><pre><code>    git remote add origin ssh://arunlinoxide@localhost:29418/linoxide.com.git
    git push -u origin master
</code></pre><p><strong>注意</strong>：強烈建議所有人修改用户名“admin”的密碼。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>歡呼吧！我們已經在Linux電腦中安裝好了最新版本的Gitblit。接下來我們便可以在我們的大小項目中享受這樣一個優美的版本控制系統。有了Gitblit，版本控制便再容易不過了。它有易於學習、輕量級、高性能的特點。因此，如果你有任何的問題、建議和反饋，請在留言處留言。</p><hr>`,36)),n("p",null,[t[6]||(t[6]=i("via: ",-1)),o(e,{href:"http://linoxide.com/linux-how-to/serve-git-repositories-gitblit/"},{default:l(()=>[...t[5]||(t[5]=[i("http://linoxide.com/linux-how-to/serve-git-repositories-gitblit/",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=i("作者：",-1)),o(e,{href:"http://linoxide.com/author/arunp/"},{default:l(()=>[...t[7]||(t[7]=[i("Arun Pyasi",-1)])]),_:1}),t[11]||(t[11]=i(" 譯者：",-1)),o(e,{href:"https://github.com/wwy-hust"},{default:l(()=>[...t[8]||(t[8]=[i("wwy-hust",-1)])]),_:1}),t[12]||(t[12]=i(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:l(()=>[...t[9]||(t[9]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=i("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[13]||(t[13]=[i("LCTT",-1)])]),_:1}),t[16]||(t[16]=i(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:l(()=>[...t[14]||(t[14]=[i("Linux中國",-1)])]),_:1}),t[17]||(t[17]=i(" 榮譽推出",-1))])])}const T=r(g,[["render",u]]);export{w as __pageData,T as default};
